-- Real transactional backend actions with synthetic identities; always rolled back.
begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,aud,role) values
 ('10000000-0000-4000-8000-000000000001','demo-owner@example.test','authenticated','authenticated'),
 ('10000000-0000-4000-8000-000000000002','demo-member@example.test','authenticated','authenticated'),
 ('10000000-0000-4000-8000-000000000003','demo-outsider@example.test','authenticated','authenticated');
create temporary table demo_test_state(key text primary key,value jsonb);
grant all on demo_test_state to service_role;
set local role authenticated;
select throws_ok($$select public.demo_api('create_team','{"team_name":"Spoofed","repository_name":"acme/demo"}','10000000-0000-4000-8000-000000000001')$$,'42501',null,'Browser cannot spoof the server actor through RPC');
reset role;
set local role service_role;
insert into demo_test_state values('team',public.demo_api('create_team','{"team_name":"Demo team","repository_name":"Acme/Demo","display_name":"Owner"}','10000000-0000-4000-8000-000000000001'));
select is((select value->'repository'->>'name' from demo_test_state where key='team'),'acme/demo','Repository normalized');
select is((select count(*)::int from public.team_members where user_id='10000000-0000-4000-8000-000000000001'),1,'Create team creates owner membership');
select throws_ok($$select public.demo_api('create_team','{"team_name":"Second team","repository_name":"acme/second"}','10000000-0000-4000-8000-000000000001')$$,'P0001','already_in_team','One team per account');
insert into demo_test_state values('invite',public.demo_api('rotate_invite',jsonb_build_object('team_id',(select value->'team'->>'id' from demo_test_state where key='team'),'new_token','ssi-'||repeat('a',64)),'10000000-0000-4000-8000-000000000001'));
select is(public.demo_api('preview_invite',jsonb_build_object('token','ssi-'||repeat('a',64)),'10000000-0000-4000-8000-000000000002')->>'state','valid','Invite preview valid');
select is(public.demo_api('accept_invite',jsonb_build_object('token','ssi-'||repeat('a',64),'display_name','Member'),'10000000-0000-4000-8000-000000000002')->>'role','member','Second account joins');
select is(public.demo_api('accept_invite',jsonb_build_object('token','ssi-'||repeat('a',64)),'10000000-0000-4000-8000-000000000002')->>'role','member','Join retry idempotent');
select throws_ok($$select public.demo_api('accept_invite',jsonb_build_object('token','ssi-'||repeat('a',64)),'10000000-0000-4000-8000-000000000003')$$,'P0001','forbidden','Free team enforces two members');
select throws_ok($$select public.demo_api('add_repository',jsonb_build_object('team_id',(select value->'team'->>'id' from demo_test_state where key='team'),'repository_name','acme/second'),'10000000-0000-4000-8000-000000000001')$$,'P0001','forbidden','Free plan enforces one repository');
insert into public.team_billing(team_id,plan,status,current_period_end) values((select (value->'team'->>'id')::uuid from demo_test_state where key='team'),'pro','active',now()+interval '30 days');
select is(public.demo_api('add_repository',jsonb_build_object('team_id',(select value->'team'->>'id' from demo_test_state where key='team'),'repository_name','acme/second'),'10000000-0000-4000-8000-000000000001')->'repository'->>'name','acme/second','Paid plan adds second repository');
select throws_ok($$select public.demo_api('add_repository',jsonb_build_object('team_id',(select value->'team'->>'id' from demo_test_state where key='team'),'repository_name','acme/third'),'10000000-0000-4000-8000-000000000002')$$,'P0001','forbidden','Only admin adds repositories');
select is(public.demo_api('accept_invite',jsonb_build_object('token','ssi-'||repeat('a',64),'display_name','Third member'),'10000000-0000-4000-8000-000000000003')->>'role','member','Active paid test plan permits third member');
select is(public.demo_api('remove_member',jsonb_build_object('team_id',(select value->'team'->>'id' from demo_test_state where key='team'),'user_id','10000000-0000-4000-8000-000000000003'),'10000000-0000-4000-8000-000000000001')->>'removed_user_id','10000000-0000-4000-8000-000000000003','Remove additional paid member');
update public.team_billing set plan='free',status='canceled' where team_id=(select (value->'team'->>'id')::uuid from demo_test_state where key='team');
select throws_ok($$select public.demo_api('rotate_invite',jsonb_build_object('team_id',(select value->'team'->>'id' from demo_test_state where key='team'),'new_token','ssi-'||repeat('b',64)),'10000000-0000-4000-8000-000000000002')$$,'P0001','forbidden','Member cannot rotate invitation');
select throws_ok($$select public.demo_api('remove_member',jsonb_build_object('team_id',(select value->'team'->>'id' from demo_test_state where key='team'),'user_id','10000000-0000-4000-8000-000000000001'),'10000000-0000-4000-8000-000000000001')$$,'P0001','last_admin','Cannot remove last admin');
insert into demo_test_state values('pair',public.demo_api('start_pairing','{"user_code":"ABCD-2345","poll_secret_hash":"abababababababababababababababababababababababababababababababab","agent":"codex","agent_version":null,"device_name":"Local demo","repository_name":"acme/demo","capabilities":{"event_capture":"partial","overlap_check":"unsupported","warning_delivery":"partial"}}'));
select is(public.demo_api('get_pairing','{"user_code":"ABCD-2345"}','10000000-0000-4000-8000-000000000001')->>'status','pending','Browser retrieves pending request');
select is(public.demo_api('poll_pairing',jsonb_build_object('pairing_id',(select value->>'pairing_id' from demo_test_state where key='pair'),'poll_secret_hash',repeat('cd',32),'device_token_hash',repeat('ef',32)))->>'status','expired','Wrong poll secret reveals no pairing');
insert into demo_test_state values('device',public.demo_api('approve_pairing','{"user_code":"ABCD-2345"}','10000000-0000-4000-8000-000000000001'));
select is(public.demo_api('poll_pairing',jsonb_build_object('pairing_id',(select value->>'pairing_id' from demo_test_state where key='pair'),'poll_secret_hash',repeat('ab',32),'device_token_hash',repeat('ef',32)))->>'status','approved','Adapter retrieves approved device once');
select is(public.demo_api('poll_pairing',jsonb_build_object('pairing_id',(select value->>'pairing_id' from demo_test_state where key='pair'),'poll_secret_hash',repeat('ab',32),'device_token_hash',repeat('ef',32)))->>'status','expired','Credential cannot be retrieved twice');
select is(public.demo_api('device_status','{}',null,repeat('ef',32))->'sharing'->>'enabled','false','Sharing starts off');
insert into demo_test_state values('event','{"events":[{"event_id":"20000000-0000-4000-8000-000000000001","session_id":"30000000-0000-4000-8000-000000000001","sequence":0,"kind":"user.message","occurred_at":"2026-10-03T20:00:00Z","redacted":true,"truncated":false,"payload":{"text":"Build a real collaboration demo","branch":"demo"}}]}');
select throws_ok($$select public.demo_api('ingest',(select value from demo_test_state where key='event'),null,repeat('ef',32))$$,'P0001','sharing_disabled','Opt-in required before ingestion');
select is(public.demo_api('set_sharing',jsonb_build_object('repository_id',(select value->'repository'->>'id' from demo_test_state where key='team'),'enabled',true),'10000000-0000-4000-8000-000000000001')->>'enabled','true','Owner opts in');
select is(public.demo_api('ingest',(select value from demo_test_state where key='event'),null,repeat('ef',32))->'results'->0->>'outcome','accepted','Device uploads a real session');
select is(public.demo_api('ingest',(select value from demo_test_state where key='event'),null,repeat('ef',32))->'results'->0->>'outcome','duplicate','Retry deduplicates stable event');
select is((select event_count from public.sessions where id='30000000-0000-4000-8000-000000000001'),1,'Duplicate does not increment session count');
select is(public.demo_api('overlap_check','{"session_id":"30000000-0000-4000-8000-000000000001","event_id":"20000000-0000-4000-8000-000000000001","prompt_text":"Build demo","branch":"demo"}',null,repeat('ef',32))->>'outcome','unavailable','Unconfigured model is unavailable, never clear');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
set local request.jwt.claims='{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}';
select is((select count(*)::int from public.session_events),1,'Teammate can see uploaded event');
select isnt(public.storage_status()->'database'->>'state','unknown','Storage measurement is fresh');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000003';
set local request.jwt.claims='{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated"}';
select is((select count(*)::int from public.session_events),0,'Outsider cannot see session');
reset role;
set local role service_role;
select throws_ok($$select public.demo_api('delete_session','{"session_id":"30000000-0000-4000-8000-000000000001"}','10000000-0000-4000-8000-000000000002')$$,'P0001','forbidden','Teammate cannot delete owner history');
select is(public.demo_api('set_sharing',jsonb_build_object('repository_id',(select value->'repository'->>'id' from demo_test_state where key='team'),'paused',true),'10000000-0000-4000-8000-000000000001')->>'paused','true','Pause sharing');
select throws_ok($$select public.demo_api('ingest',(select value from demo_test_state where key='event'),null,repeat('ef',32))$$,'P0001','sharing_paused','Paused device stops uploads');
select is(public.demo_api('set_sharing',jsonb_build_object('repository_id',(select value->'repository'->>'id' from demo_test_state where key='team'),'paused',false),'10000000-0000-4000-8000-000000000001')->>'paused','false','Resume sharing');
select is(public.demo_api('set_session_visibility','{"session_id":"30000000-0000-4000-8000-000000000001","visibility":"private"}','10000000-0000-4000-8000-000000000001')->'session'->>'visibility','private','Owner makes session private');
select is(public.demo_api('ingest',(select value from demo_test_state where key='event'),null,repeat('ef',32))->'results'->0->>'code','session_private','Private sessions reject future uploads');
select is(public.demo_api('set_session_visibility','{"session_id":"30000000-0000-4000-8000-000000000001","visibility":"shared"}','10000000-0000-4000-8000-000000000001')->'session'->>'visibility','shared','Owner resumes session sharing');
select is(public.demo_api('delete_session','{"session_id":"30000000-0000-4000-8000-000000000001"}','10000000-0000-4000-8000-000000000001')->'session'->>'history_removed_reason','owner_deleted','Owner deletion leaves tombstone');
select is((select count(*)::int from public.session_events),0,'Deleted events gone');
select is((select request_excerpt from public.overlap_checks limit 1),null::text,'Deleted overlap source excerpt gone');
select is(public.demo_api('ingest',(select value from demo_test_state where key='event'),null,repeat('ef',32))->'results'->0->>'code','history_removed','Deleted history cannot be resurrected');
-- Drive the bounded sliding window using accounted sizes, without allocating 40 MB of source.
insert into demo_test_state values('event2',jsonb_set(jsonb_set((select value from demo_test_state where key='event'),'{events,0,event_id}','"20000000-0000-4000-8000-000000000002"'),'{events,0,session_id}','"30000000-0000-4000-8000-000000000002"'));
select is(public.demo_api('ingest',(select value from demo_test_state where key='event2'),null,repeat('ef',32))->'results'->0->>'outcome','accepted','New session after deletion accepted');
update private.session_usage set bytes=40000000 where session_id='30000000-0000-4000-8000-000000000002';
update private.user_usage set accounted_bytes=40001024 where user_id='10000000-0000-4000-8000-000000000001';
insert into demo_test_state values('event3',jsonb_set(jsonb_set((select value from demo_test_state where key='event'),'{events,0,event_id}','"20000000-0000-4000-8000-000000000003"'),'{events,0,session_id}','"30000000-0000-4000-8000-000000000003"'));
select is(public.demo_api('ingest',(select value from demo_test_state where key='event3'),null,repeat('ef',32))->>'storage_state','cleanup','Crossing warning threshold prunes before admitting upload');
select is((select history_removed_reason from public.sessions where id='30000000-0000-4000-8000-000000000002'),'pruned','Oldest history pruned');
select ok((select accounted_bytes<30000000 from private.user_usage where user_id='10000000-0000-4000-8000-000000000001'),'Window reduced below target');
select is((select count(*)::int from public.cleanup_notices where reason='quota'),1,'Owner receives cleanup notice');
-- Provider evidence is selected by the database, scoped to current teammates/repository.
insert into public.devices(id,user_id,team_id,repository_id,name,agent,capabilities)
select '40000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000002',(value->'team'->>'id')::uuid,(value->'repository'->>'id')::uuid,'Teammate device','codex','{"event_capture":"partial","overlap_check":"supported","warning_delivery":"partial"}' from demo_test_state where key='team';
insert into private.device_credentials(device_id,token_hash) values('40000000-0000-4000-8000-000000000004',decode(repeat('bc',32),'hex'));
insert into public.sessions(id,team_id,repository_id,user_id,device_id,agent,started_at,last_activity_at)
select '30000000-0000-4000-8000-000000000004',(value->'team'->>'id')::uuid,(value->'repository'->>'id')::uuid,'10000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000004','codex',now(),now() from demo_test_state where key='team';
insert into public.session_events(id,session_id,team_id,sequence,kind,occurred_at,redacted,truncated,payload)
select '20000000-0000-4000-8000-000000000004','30000000-0000-4000-8000-000000000004',(value->'team'->>'id')::uuid,0,'user.message',now(),true,false,'{"text":"Build a real collaboration demo","branch":"teammate"}' from demo_test_state where key='team';
insert into demo_test_state values('check_payload','{"session_id":"30000000-0000-4000-8000-000000000003","event_id":"20000000-0000-4000-8000-000000000003","prompt_text":"Spoofed client text","branch":null}');
select is(public.demo_api('overlap_context',(select value from demo_test_state where key='check_payload'),null,repeat('ef',32))->>'request_text','Build a real collaboration demo','Provider receives persisted prompt, not spoofed request text');
select is(jsonb_array_length(public.demo_api('overlap_context',(select value from demo_test_state where key='check_payload'),null,repeat('ef',32))->'candidates'),1,'Provider sees only authorized recent teammate evidence');
insert into demo_test_state values('evaluation','{"outcome":"warning","unavailable_reason":null,"findings":[{"related_session_id":"30000000-0000-4000-8000-000000000004","related_user_id":"10000000-0000-4000-8000-000000000002","relation":"overlapping","score":0.9,"summary":"Potential implementation overlap.","evidence":[{"session_id":"30000000-0000-4000-8000-000000000004","event_id":"20000000-0000-4000-8000-000000000004","excerpt":"Build a real collaboration demo"}]}]}');
select is(public.demo_api('overlap_check',(select value from demo_test_state where key='check_payload')||jsonb_build_object('_evaluation',(select value from demo_test_state where key='evaluation'),'_source_context','[{"session_id":"30000000-0000-4000-8000-000000000004","user_id":"10000000-0000-4000-8000-000000000002","event_id":"20000000-0000-4000-8000-000000000004"}]'::jsonb),null,repeat('ef',32))->>'outcome','warning','Validated provider result persists with grounded source');
select is(public.demo_api('overlap_context',(select value from demo_test_state where key='check_payload'),null,repeat('ef',32))->'cached'->>'outcome','warning','Check retry returns original stored result');
select is(public.demo_api('delete_session','{"session_id":"30000000-0000-4000-8000-000000000004"}','10000000-0000-4000-8000-000000000002')->'session'->>'history_removed_reason','owner_deleted','Teammate removes their source history');
select is((select outcome from public.overlap_checks where trigger_event_id='20000000-0000-4000-8000-000000000003'),'unavailable','Source deletion invalidates warning without stale quotations');
select is((select findings::text from public.overlap_checks where trigger_event_id='20000000-0000-4000-8000-000000000003'),'[]','Source deletion clears all associated quotations');
select throws_ok($$select public.demo_api('revoke_device',jsonb_build_object('device_id',(select value->'device'->>'id' from demo_test_state where key='device')),'10000000-0000-4000-8000-000000000002')$$,'P0001','forbidden','Teammate cannot revoke owner device');
select is(public.demo_api('revoke_device',jsonb_build_object('device_id',(select value->'device'->>'id' from demo_test_state where key='device')),'10000000-0000-4000-8000-000000000001')->'device'->>'status','revoked','Owner revokes device');
select throws_ok($$select public.demo_api('ingest',(select value from demo_test_state where key='event3'),null,repeat('ef',32))$$,'P0001','device_revoked','Revoked device cannot upload');
select throws_ok($$select public.demo_api('device_status','{}',null,repeat('bb',32))$$,'P0001','device_unknown','Unknown device token cannot authenticate');
select is(public.demo_api('remove_member',jsonb_build_object('team_id',(select value->'team'->>'id' from demo_test_state where key='team'),'user_id','10000000-0000-4000-8000-000000000002'),'10000000-0000-4000-8000-000000000001')->>'removed_user_id','10000000-0000-4000-8000-000000000002','Owner removes member');
select throws_ok($$select public.demo_api('device_status','{}',null,repeat('bc',32))$$,'P0001','device_revoked','Member removal revokes their device atomically');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
set local request.jwt.claims='{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}';
select is((select count(*)::int from public.sessions),0,'Removed member immediately loses session access');
reset role;
select * from finish();
rollback;
